WITH with_gaps AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL 20 MINUTES THEN 1 ELSE 0 END AS is_new_burst FROM device_readings), sessions_device_readings AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT DATE_TRUNC('HOUR', reading_ts) AS hour_window, DATE_TRUNC('DAY', reading_ts) AS activity_day, device_code, ROUND(AVG(pressure), 2) AS avg_pressure, SIZE(COLLECT_SET(device_code)) AS num_device_codes, SORT_ARRAY(COLLECT_SET(device_code)) AS device_code_list FROM sessions_device_readings GROUP BY hour_window, activity_day, device_code HAVING num_device_codes >= 1 ORDER BY device_code DESC NULLS LAST;
